mapper.select:
select
a.id,
b.code as grid_code,
coalesce(a.grid_name, b.name) as grid_name,
grid_customer_total,
grid_main_manager_name,
grid_main_manager_code,
grid_side_manager_name,
grid_side_manager_code,
belong_team,
first_level_branch,
second_level_branch,
branch, picture,
create_time, a.update_time,
grid_overview,grid_remark,coalesce(a.rural_grid_type, b.rural_grid_type) as rural_grid_type,is_modify,peers_num,
community_num,district_num,hiq_units_num,hiq_units_situation,
grid_main_manager_phone,duty_network_name,duty_network_code,duty_name,
duty_code,duty_phone,bank_agency_name,bank_agency_code,
duty_network_address,duty_telephone,is_cash
from pa_addr_info_type b
    left join grid_message_info a on a.grid_code = b.code

    b.addr_level = 5
    and b.code = #{gridCode }
    and b.ancestor_codes  like concat('%,',#{code},',%')
    and coalesce(a.grid_name, b.name) like concat ('%',#{gridName},'%')
    and grid_customer_total =
        #{gridCustomerTotal }

    and grid_main_manager_name =
        #{gridMainManagerName }

    and grid_main_manager_code =
        #{gridMainManagerCode }

    and grid_side_manager_name =
        #{gridSideManagerName ,typeHandler=com.kx.system.config.typehandler.ListStringTypeHandler}

    and grid_side_manager_code =
        #{gridSideManagerCode ,typeHandler=com.kx.system.config.typehandler.ListStringTypeHandler}

    and belong_team = #{belongTeam }
    and first_level_branch = #{firstLevelBranch }
    and second_level_branch = #{secondLevelBranch }
    and branch = #{branch }
    and picture = #{picture }
    and create_time = #{createTime }
    and update_time = #{updateTime }
    and grid_overview = #{gridOverview}
    and grid_remark = #{gridRemark}
    and a.rural_grid_type = #{ruralGridType}
    and is_cash = #{isCash}
    and duty_network_name = #{dutyNetworkName}

        and

            duty_network_name = #{item}

