select grid_code
from grid_message_info
where grid_name = #{gridName}

select distinct p.code, p.name, a2.name as zjName, a3.name as xyName, case when p.rural_grid_type like '%0%' then '行政村' when p.rural_grid_type like '%1%' then '社区' else '其他' end as ruralGridType, case when g.is_cash like '%0%' then '否' when g.is_cash like '%1%' then '是' end as isCash, g.grid_main_manager_name, g.grid_main_manager_phone, g.duty_network_name, case when g.duty_network_name is null then b.anchor_name end as ordinaryNetwork, c.serve_point_name as cServePointName , c.serve_point_addr as cServePointAddr, m.import_name, m.import_address, v.serve_point_name as vServePointName , v.serve_point_addr as vServePointaddr, r.police_name, r.police_address, r.un_faker_mobile, r.un_faker_name, r.un_faker_phone, d.supervisor_name, d.supervisor_phone from pa_addr_info_type p left join grid_message_info g on p.code = g.grid_code left join cash_service_points c on p.code = c.grid_code left join village_financial_service_points v on p.code = v.grid_code left join grid_rating_info r on p.parent_code = r.grid_code left join grid_manage_objects m on p.code = m.grid_code left join anchor_point b on p.code = b.belong_grid left join grid_community_supervisors d on p.code = d.grid_code left join pa_addr_info_type a2 on a2.code = p.parent_code left join pa_addr_info_type a3 on a3.code = a2.parent_code
p.addr_level = 5 and g.grid_code = #{gridCode } and p.ancestor_codes like concat('%,',#{code},',%') and g.grid_name like concat ('%',#{gridName},'%') and g.rural_grid_type = #{ruralGridType} and is_cash = #{isCash} and duty_network_name = #{dutyNetworkName}
and
duty_network_name = #{item}
order by p.code;

select distinct p.code, p.name, a2.name as zjName, a3.name as xyName, case when p.rural_grid_type like '%0%' then '行政村' when p.rural_grid_type like '%1%' then '社区' else '其他' end as ruralGridType, case when g.is_cash like '%0%' then '否' when g.is_cash like '%1%' then '是' end as isCash, g.grid_main_manager_name, g.grid_main_manager_phone, g.duty_network_name, case when g.duty_network_name is null then b.anchor_name end as ordinaryNetwork, c.serve_point_name as cServePointName , c.serve_point_addr as cServePointAddr, m.import_name, m.import_address, v.serve_point_name as vServePointName , v.serve_point_addr as vServePointaddr, r.police_name, r.police_address, r.un_faker_mobile, r.un_faker_name, r.un_faker_phone, d.supervisor_name, d.supervisor_phone from pa_addr_info_type p left join grid_message_info g on p.code = g.grid_code left join cash_service_points c on p.code = c.grid_code left join village_financial_service_points v on p.code = v.grid_code left join grid_rating_info r on p.parent_code = r.grid_code left join grid_manage_objects m on p.code = m.grid_code left join anchor_point b on p.code = b.belong_grid left join grid_community_supervisors d on p.code = d.grid_code left join pa_addr_info_type a2 on a2.code = p.parent_code left join pa_addr_info_type a3 on a3.code = a2.parent_code
p.addr_level = 5 and g.grid_code = #{gridCode } and p.ancestor_codes like concat('%,',#{code},',%') and g.grid_name like concat ('%',#{gridName},'%') and g.rural_grid_type = #{ruralGridType} and is_cash = #{isCash} and duty_network_name = #{dutyNetworkName}
and
duty_network_name = #{item}
order by p.code;

update.foreach:
update grid_message_info

    duty_name = #{item.dutyName},
